// Reuse the fixed 5AG OS-only dependency registration and fixtures; no HIL state seam.
#define main baseline_activation_main
#include "common_world_activation_tests.cpp"
#undef main
#include "monaka_bridge/common_world_deployment_readiness.hpp"
#include "monaka_bridge/network.hpp"
void arm(Rig& r) { r.config["enabled"]=false; r.save(); CHECK(r.runtime->prepareArmed(r.path,r.f.authority,2)=="armed-disabled"); }
CommonWorldControlRequest command(Rig& r,const std::string& op) {
 const auto s=r.runtime->snapshot(); CommonWorldControlRequest q;
 q.operationId="test-operation-"+std::to_string(checks); q.operation=op;
 q.runtimeInstance=s.runtimeInstance; q.controlSession=s.controlSession; q.sourceLease=s.sourceLease;
 q.sourceGeneration=s.sender?s.sender->ingress.sourceGeneration:0; return q;
}
std::string readyToken(Rig& r) { CHECK(r.runtime->refreshReadiness()=="readiness-current"); auto s=r.runtime->snapshot(); CHECK(s.readinessValid && !s.readinessToken.empty()); return s.readinessToken; }
void activeArmed(Rig& r) { arm(r); auto token=readyToken(r); CHECK(r.runtime->activateReady(token,true,3)=="active"); }
int main(int argc,char** argv) try {
 CHECK(argc==2); const auto root=fs::path(argv[1])/std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()); fs::create_directories(root);
 auto rig=[&] { return std::make_unique<Rig>(root/std::to_string(cases)); };
 run("01 prepare ArmedDisabled retains exact instance and OFF",[&] { auto r=rig(); auto before=r->runtime->snapshot(); arm(*r); auto s=r->runtime->snapshot(); CHECK(s.runtimeInstance==before.runtimeInstance && s.controlSession==before.controlSession); CHECK(s.status==CommonWorldActivationStatus::ArmedDisabled && !s.configurationEnabled); });
 run("02 armed pump cannot publish",[&] { auto r=rig(); arm(*r); CHECK(r->runtime->pump().status=="activation-inactive"); CHECK(r->sink->connects==0 && r->sink->calls==0 && !r->runtime->snapshot().sender->queued); });
 run("03 armed input does not queue publication",[&] { auto r=rig(); arm(*r); auto q=command(*r,"input"); q.envelope=r->f.pose; CHECK(r->runtime->control(q,4).result=="pose"); CHECK(r->sink->calls==0 && !r->runtime->snapshot().sender->queued); });
 run("04 status is available and side effect free",[&] { auto r=rig(); arm(*r); const auto b=r->runtime->snapshot(); auto q=command(*r,"status"); auto x=r->runtime->control(q,5); CHECK(x.accepted && x.after.generation==b.generation && x.after.lastOperation==b.lastOperation); CHECK(r->runtime->snapshot().runtimeInstance==b.runtimeInstance); });
 run("05 armed shutdown clean and idempotent",[&] { auto r=rig(); arm(*r); auto q=command(*r,"shutdown"); CHECK(r->runtime->control(q,6).accepted); auto s=r->runtime->snapshot(); CHECK(s.shutdown && s.sender->disposed && !s.sender->queued && !s.sender->connected); CHECK(r->runtime->control(q,7).after.generation==s.generation); });
 run("06 fresh readiness binds current instance",[&] { auto r=rig(); arm(*r); auto t=readyToken(*r); CHECK(r->runtime->activateReady(t,true,4)=="active"); CHECK(r->runtime->snapshot().readinessToken.empty()); });
 run("07 old refreshed token rejects",[&] { auto r=rig(); arm(*r); auto old=readyToken(*r); auto fresh=readyToken(*r); CHECK(old!=fresh && r->runtime->activateReady(old,true,4)=="stale-readiness"); CHECK(!r->sink->connects); });
 run("08 owner revoke invalidates readiness",[&] { auto r=rig(); arm(*r); auto t=readyToken(*r); r->runtime->revokeOwner(5); CHECK(!r->runtime->snapshot().readinessValid && r->runtime->activateReady(t,true,6)=="stale-readiness"); });
 run("09 durable epoch handover invalidates readiness",[&] { auto r=rig(); arm(*r); auto t=readyToken(*r); r->handover(); CHECK(!r->runtime->snapshot().readinessValid); CHECK(r->runtime->activateReady(t,true,6)=="stale-epoch-or-receipt" && !r->sink->connects); });
 run("10 world/source identity change invalidates readiness",[&] { auto r=rig(); arm(*r); auto t=readyToken(*r); auto a=r->f.authority; a.sequence=1; ++a.source_space.source_space_generation; CHECK(r->runtime->receive(a,5).source.status=="authority"); CHECK(r->runtime->activateReady(t,true,6)=="stale-readiness" && !r->runtime->snapshot().readinessValid); });
 for(const auto& field:{"endpoint","owner_id","world_space_id","source_publisher_id","transport","codec","revision_path","queue_capacity"}) run(std::string("11-18 config change freshness ")+field,[&] { auto r=rig(); arm(*r); auto t=readyToken(*r); if(std::string(field)=="queue_capacity") r->config[field]=65; else r->config[field]="changed-value"; r->save(); CHECK(!r->runtime->snapshot().readinessValid); CHECK(r->runtime->activateReady(t,true,7)=="configuration-changed" && !r->sink->connects); });
 run("19 emergency invalidates readiness and is terminal",[&] { auto r=rig(); arm(*r); auto t=readyToken(*r); r->runtime->emergencyRevoke(5); CHECK(r->runtime->activateReady(t,true,6)=="shutdown"); auto b=r->runtime->snapshot(); r->runtime->emergencyRevoke(7); CHECK(b.emergencyRevoked && b.ownerRevoked && b.generation==r->runtime->snapshot().generation); });
 run("20 runtime replacement rejects token and control",[&] { auto r=rig(); arm(*r); auto t=readyToken(*r); auto q=command(*r,"activate"); q.readinessToken=t; q.explicitEnable=true; Rig other(root/"replacement"); arm(other); CHECK(other.runtime->activateReady(t,true,5)=="stale-readiness"); CHECK(other.runtime->control(q,6).result=="stale-control-session"); });
 run("21 raw activation cannot bypass armed readiness",[&] { auto r=rig(); arm(*r); CHECK(r->runtime->activate(r->world(),4)=="current-readiness-required"); CHECK(r->runtime->activateReady(readyToken(*r),false,5)=="explicit-enable-required"); });
 run("22 snapshot completeness and no configuration leak",[&] { auto r=rig(); arm(*r); auto j=J::parse(commonWorldRuntimeDiagnostics(r->runtime->snapshot(),parseCommonWorldActivationConfig(r->config.dump(),r->path,true),"test-commit")); for(auto name:{"schema","runtime_instance","control_session","owner_epoch","store","sender","readiness","gate_state","last_control_operation","observed_at_unix_ms"}) CHECK(j.contains(name)); auto sender=j["sender"]; for(auto name:{"source_generation","source_session","source_clock","source_sequence_high_water","queue_depth","queue_high_water","transport_generation","local_submission_record","current_source_authority"}) CHECK(sender.contains(name)); CHECK(j["store"]["current_authorization_epoch"]==j["owner_epoch"]); CHECK(j.dump().find(r->path.string())==std::string::npos && j.dump().find("test://sink")==std::string::npos); });
 run("23 local submission record at guarded boundary",[&] { auto r=rig(); activeArmed(*r); CHECK(r->runtime->pump().status=="local-accepted"); auto s=r->runtime->snapshot(); const auto& x=*s.sender->lastSubmission; CHECK(x.ownerEpoch==s.ownerEpoch && x.worldEpoch==r->world().world_epoch && x.transportGeneration==s.sender->transportGeneration); CHECK(x.result=="local-accepted" && x.sequence==0 && x.orderingPosition==1 && x.monotonicNs>0); });
 run("24 consumed readiness cannot activate twice",[&] { auto r=rig(); arm(*r); auto t=readyToken(*r); CHECK(r->runtime->activateReady(t,true,3)=="active"); CHECK(r->runtime->activateReady(t,true,4)=="stale-readiness" && r->sink->connects==1); });
 run("25 deactivate queued send then fresh approval",[&] { auto r=rig(); activeArmed(*r); CHECK(r->runtime->snapshot().sender->queued==2); r->runtime->deactivate(); auto b=r->runtime->snapshot(); CHECK(b.status==CommonWorldActivationStatus::ArmedDisabled && !b.sender->queued && !b.sender->enabled); CHECK(r->runtime->pump().status=="activation-inactive"); r->runtime->deactivate(); CHECK(r->runtime->snapshot().generation==b.generation); CHECK(r->runtime->activateReady(readyToken(*r),true,9)=="active"); });
 run("26 owner revoke blocks publication and reconnect authorization",[&] { auto r=rig(); activeArmed(*r); r->runtime->revokeOwner(5); CHECK(!r->runtime->snapshot().sender->enabled && !r->runtime->snapshot().sender->queued); r->runtime->reconnectSource(6); CHECK(r->runtime->authorizeReconnectedSource(r->f.authority,7)=="authorization-revoked" && !r->runtime->snapshot().sender->ingress.ownerApproved); });
 run("27 source reconnect fresh generation no authority",[&] { auto r=rig(); arm(*r); auto b=r->runtime->snapshot(); CHECK(r->runtime->reconnectSource(6)=="source-reconnected-awaiting-explicit-authorization"); auto s=r->runtime->snapshot(); CHECK(s.sender->ingress.sourceGeneration>b.sender->ingress.sourceGeneration && s.sourceLease!=b.sourceLease && s.ownerEpoch==b.ownerEpoch); CHECK(!s.sender->ingress.ownerApproved && !s.sender->enabled && s.durableState->highWater.lastWorldRevision==b.durableState->highWater.lastWorldRevision); });
 run("28 old source lease/generation rejected",[&] { auto r=rig(); arm(*r); auto q=command(*r,"input"); q.envelope=r->f.pose; r->runtime->reconnectSource(6); CHECK(r->runtime->control(q,7).result=="stale-source"); });
 run("29 fresh producer authorization durable successor",[&] { auto r=rig(); arm(*r); auto b=r->runtime->snapshot(); r->runtime->reconnectSource(6); auto a=r->f.authority; a.session_id=mb::uuid(); a.clock_id=mb::uuid(); auto q=command(*r,"source-authorize"); q.envelope=a; CHECK(r->runtime->control(q,7).result=="source-authorized-armed-disabled"); auto s=r->runtime->snapshot(); CHECK(s.status==CommonWorldActivationStatus::ArmedDisabled && s.ownerEpoch==b.ownerEpoch && s.sender->ingress.ownerApproved); CHECK(s.durableState->highWater.lastWorldRevision>b.durableState->highWater.lastWorldRevision && !s.sender->enabled && !r->sink->connects); });
 run("30 reused producer session rejected after reconnect",[&] { auto r=rig(); arm(*r); r->runtime->reconnectSource(6); CHECK(r->runtime->authorizeReconnectedSource(r->f.authority,7)!="source-authorized-armed-disabled"); CHECK(!r->runtime->snapshot().sender->ingress.ownerApproved); });
 run("31 transport reconnect OFF retires fresh session no connect",[&] { auto r=rig(); arm(*r); auto b=r->runtime->snapshot(); CHECK(r->runtime->reconnectTransport(6)=="transport-retired-disabled"); auto s=r->runtime->snapshot(); CHECK(s.sender->transportGeneration>b.sender->transportGeneration && !s.sender->enabled && !r->sink->connects); });
 run("32 active reconnect gated fresh session",[&] { auto r=rig(); activeArmed(*r); auto b=r->runtime->snapshot(); CHECK(r->runtime->reconnectTransport(6)=="active"); auto s=r->runtime->snapshot(); CHECK(s.sender->transportGeneration>b.sender->transportGeneration && s.sender->publisherGeneration>b.sender->publisherGeneration && r->sink->connects==2); });
 run("33 old transport completion cannot update current record",[&] { auto r=rig(); activeArmed(*r); r->sink->mode=DatagramSubmission::Pending; auto pending=r->runtime->pump(); CHECK(bool(pending.completion)); auto old=r->runtime->snapshot().sender->lastSubmission; CHECK(r->runtime->reconnectTransport(6)=="active"); CHECK(r->runtime->complete(pending.completion,{DatagramSubmission::Accepted,r->sink->frames[0].size()})=="stale-completion"); CHECK(r->runtime->snapshot().sender->lastSubmission->result==old->result); });
 run("34 reconnect revalidates external epoch",[&] { auto r=rig(); activeArmed(*r); r->handover(); CHECK(r->runtime->reconnectTransport(6)=="reconnect-authorization-retired" && r->sink->connects==1); CHECK(!r->runtime->snapshot().sender->enabled); });
 run("35 reconnect revalidates owner",[&] { auto r=rig(); activeArmed(*r); r->runtime->revokeOwner(5); CHECK(r->runtime->reconnectTransport(6)=="transport-retired-disabled" && r->sink->connects==1); CHECK(!r->runtime->snapshot().sender->ingress.ownerApproved); });
 run("36 continuous trusted input preserves authority and sequence",[&] { auto r=rig(); arm(*r); for(int i=1;i<=4;++i) { auto p=r->f.pose; p.sequence=i; p.source.observation_id=i; auto q=command(*r,"input"); q.envelope=p; CHECK(r->runtime->control(q,5+i).result=="pose"); } CHECK(r->runtime->snapshot().sender->ingress.runtime.sourceSequence==4); });
 run("37 wrong publisher rejected",[&] { auto r=rig(); arm(*r); auto p=r->f.pose; p.publisher_id="wrong"; auto q=command(*r,"input"); q.envelope=p; CHECK(r->runtime->control(q,5).result=="unauthorized"); CHECK(r->runtime->snapshot().sender->ingress.runtime.sourceSequence==0); });
 run("38 invalid authority token rejected",[&] { auto r=rig(); arm(*r); auto p=r->f.pose; ++p.source.source_space.source_space_generation; auto q=command(*r,"input"); q.envelope=p; CHECK(r->runtime->control(q,5).result=="untrusted"); CHECK(!r->runtime->snapshot().sender->ingress.sourceActive); });
 run("39 stale sequence rejected without advancement",[&] { auto r=rig(); arm(*r); CHECK(r->runtime->receive(r->f.pose,5).source.status=="pose"); CHECK(r->runtime->receive(r->f.authority,6).source.status=="old"); CHECK(r->runtime->snapshot().sender->ingress.runtime.sourceSequence==1); });
 run("40 sequence gap retires authority",[&] { auto r=rig(); arm(*r); auto p=r->f.pose; p.sequence=3; CHECK(r->runtime->receive(p,5).source.status=="gap"); CHECK(!r->runtime->snapshot().sender->ingress.ownerApproved); });
 run("41 producer disconnect observable",[&] { auto r=rig(); arm(*r); auto q=command(*r,"source-disconnect"); CHECK(r->runtime->control(q,5).result=="producer-disconnected"); CHECK(!r->runtime->snapshot().sender->ingress.sourceActive && !r->runtime->snapshot().sender->enabled); });
 run("42 producer EOF explicit but runtime retained",[&] { auto r=rig(); arm(*r); auto id=r->runtime->snapshot().runtimeInstance; CHECK(r->runtime->control(command(*r,"source-eof"),5).result=="producer-eof"); CHECK(!r->runtime->snapshot().shutdown && r->runtime->snapshot().runtimeInstance==id); });
 run("43 temporary no-data/status keeps generation",[&] { auto r=rig(); arm(*r); const auto b=r->runtime->snapshot(); for(int i=0;i<20;++i) CHECK(r->runtime->control(command(*r,"snapshot"),i+5).after.generation==b.generation); CHECK(r->runtime->snapshot().sender->ingress.sourceGeneration==b.sender->ingress.sourceGeneration); });
 for(bool emergency:{false,true}) run(emergency?"45 activate vs emergency revoke":"44 activate vs owner revoke",[&] { Barrier b; Rig r(root/std::to_string(cases),[&](auto stage) { if(stage==CommonWorldStartupStage::TransportActivation) b.block(); }); arm(r); auto token=readyToken(r); auto activating=std::async(std::launch::async,[&] { return r.runtime->activateReady(token,true,5); }); b.wait(); std::promise<void> started; auto revoking=std::async(std::launch::async,[&] { started.set_value(); if(emergency) r.runtime->emergencyRevoke(6); else r.runtime->revokeOwner(6); }); started.get_future().wait(); b.release(); CHECK(activating.get()=="active"); revoking.get(); auto s=r.runtime->snapshot(); CHECK(!s.sender->enabled && !s.sender->queued && !s.readinessValid); CHECK(r.runtime->pump().status=="activation-inactive"); });
 run("46 source reconnect vs delayed old input",[&] { auto r=rig(); arm(*r); auto old=command(*r,"input"); old.envelope=r->f.pose; Barrier b; auto f=std::async(std::launch::async,[&] { b.block(); return r->runtime->control(old,8); }); b.wait(); r->runtime->reconnectSource(7); b.release(); CHECK(f.get().result=="stale-source"); });
 run("47 deactivate vs delayed completion",[&] { auto r=rig(); activeArmed(*r); r->sink->mode=DatagramSubmission::Pending; auto attempt=r->runtime->pump(); CHECK(bool(attempt.completion)); r->runtime->deactivate(); CHECK(r->runtime->complete(attempt.completion,{DatagramSubmission::Accepted,1})=="stale-completion"); CHECK(!r->runtime->snapshot().sender->queued && !r->sink->connected); });
 run("48 shutdown vs delayed control activation",[&] { auto r=rig(); arm(*r); auto q=command(*r,"activate"); q.readinessToken=readyToken(*r); q.explicitEnable=true; Barrier b; auto f=std::async(std::launch::async,[&] { b.block(); return r->runtime->control(q,8); }); b.wait(); r->runtime->shutdown(7); b.release(); CHECK(f.get().result=="shutdown" && !r->sink->connects); });
 run("49 concurrent snapshot/control coherent generations",[&] { auto r=rig(); arm(*r); auto f=std::async(std::launch::async,[&] { return r->runtime->control(command(*r,"source-reconnect"),6); }); auto s=r->runtime->snapshot(); auto x=f.get(); CHECK(x.after.generation>x.before.generation); CHECK(s.generation==x.before.generation || s.generation==x.after.generation); CHECK(x.before.runtimeInstance==x.after.runtimeInstance); });
 run("50 stale control client cannot revoke/activate/shutdown",[&] { auto r=rig(); arm(*r); for(auto op:{"activate","owner-revoke","emergency-revoke","shutdown","source-reconnect"}) { auto q=command(*r,op); q.controlSession="retired-control"; auto x=r->runtime->control(q,6); CHECK(x.result=="stale-control-session" && x.after.generation==x.before.generation); } CHECK(!r->runtime->snapshot().ownerRevoked); });

 run("51 current store observation detects epoch mismatch",[&] { auto r=rig(); arm(*r); auto before=r->runtime->snapshot(); CHECK(before.durableReceiptCurrent); r->handover(); auto after=r->runtime->snapshot(); CHECK(!after.durableReceiptCurrent && after.durableState->currentAuthorizationEpoch!=after.ownerEpoch); });
 run("52 accepted and rejected input diagnostics",[&] { auto r=rig(); arm(*r); CHECK(r->runtime->receive(r->f.pose,5).source.status=="pose"); auto wrong=r->f.pose; wrong.publisher_id="wrong"; CHECK(r->runtime->receive(wrong,6).source.status=="unauthorized"); auto s=r->runtime->snapshot(); CHECK(s.lastAcceptedSourceResult=="pose" && s.lastAcceptedSourceSequence==1 && s.lastAcceptedSourceNs==5); CHECK(s.lastRejectedSourceResult=="unauthorized" && s.lastRejectedSourceNs==6); });
 run("53 source identity transition stale readiness",[&] { auto r=rig(); arm(*r); auto t=readyToken(*r); auto a=r->f.authority; a.sequence=1; a.source_space.source_id="new-source-id"; a.source_space.source_authority_session_epoch="new-source-token"; CHECK(r->runtime->receive(a,6).source.status=="authority"); CHECK(r->runtime->activateReady(t,true,7)=="stale-readiness"); });
 run("54 exception local submission remains observational",[&] { auto r=rig(); activeArmed(*r); r->sink->throwSubmit=true; CHECK(r->runtime->pump().status=="submission-exception-ambiguous"); auto s=r->runtime->snapshot(); CHECK(s.sender->lastSubmission && s.sender->lastSubmission->result=="local-exception-ambiguous"); CHECK(!s.sender->enabled && !s.sender->queued); });
 run("55 rejected local submission classification",[&] { auto r=rig(); activeArmed(*r); r->sink->mode=DatagramSubmission::Rejected; CHECK(r->runtime->pump().status=="retryable-rejection"); CHECK(r->runtime->snapshot().sender->lastSubmission->result=="local-rejected" && !r->runtime->snapshot().sender->lastLocalAcceptedSequence); });
 run("56 config syntax secrets are not emitted",[&] { auto r=rig(); std::ofstream(r->path)<<"{\"enabled\":false,\"secret\":\"SYNTHETIC_SECRET"; CHECK(r->runtime->prepareArmed(r->path,r->f.authority,2)=="startup-failed"); auto j=commonWorldRuntimeDiagnostics(r->runtime->snapshot(),{},"test"); CHECK(j.find("SYNTHETIC_SECRET")==std::string::npos); });
 for(bool sourceAuthorization:{false,true}) run(sourceAuthorization?"58 revoke during source-authorize durable IO":"57 revoke during control prepare durable IO",[&] {
  Barrier b; auto record=std::make_shared<Record>(); auto sink=std::make_shared<Sink>(); auto block=std::make_shared<std::atomic_bool>(false);
  struct PausedStorage final:CommonWorldRevisionStorage {
   Storage inner; Barrier& barrier; std::shared_ptr<std::atomic_bool> block;
   PausedStorage(std::shared_ptr<Record> r,Barrier& b,std::shared_ptr<std::atomic_bool> pause):inner(std::move(r)),barrier(b),block(std::move(pause)) {}
   std::optional<std::string> readCommitted() override { return inner.readCommitted(); }
   void atomicWrite(const std::string& bytes,const std::atomic_bool* c) override { if(block->exchange(false)) barrier.block(); inner.atomicWrite(bytes,c); }
  };
  Rig r(root/std::to_string(cases)); r.record=record; r.sink=sink;
  r.runtime=CommonWorldActivationTestRegistration::make(record,sink,{}, {},false,[&](const fs::path&) { return std::make_unique<PausedStorage>(record,b,block); });
  r.config["enabled"]=false; r.save(); CommonWorldControlRequest q;
  if(sourceAuthorization) { CHECK(r.runtime->prepareArmed(r.path,r.f.authority,2)=="armed-disabled"); r.runtime->reconnectSource(3); q=command(r,"source-authorize"); auto a=r.f.authority; a.session_id=mb::uuid(); a.clock_id=mb::uuid(); q.envelope=a; }
  else { q=command(r,"prepare"); q.config=r.path; q.envelope=r.f.authority; }
  block->store(true); auto pending=std::async(std::launch::async,[&] { return r.runtime->control(q,4); }); b.wait();
  auto revoke=std::async(std::launch::async,[&] { return r.runtime->control(command(r,"owner-revoke"),5); });
  const bool independent=revoke.wait_for(std::chrono::seconds(5))==std::future_status::ready;
  b.release(); auto revoked=revoke.get(); auto result=pending.get(); CHECK(independent && revoked.accepted && !result.accepted);
  CHECK(result.result=="startup-retired" || result.result=="source-authorization-retired"); CHECK(!r.sink->calls && !r.sink->connects);
 });
 run("59 strict empty armed config cannot open store",[&] { auto r=rig(); std::ofstream(r->path)<<""; CHECK(r->runtime->prepareArmed(r->path,r->f.authority,2)=="startup-failed"); CHECK(!r->record->bytes && r->sink->connects==0); CHECK(r->runtime->snapshot().status==CommonWorldActivationStatus::ConfigInvalid); });
 run("60 paired snapshot timestamps bind to capture not serialization",[&] { auto r=rig(); arm(*r); const auto x=r->runtime->control(command(*r,"source-reconnect"),6); CHECK(x.before.observedAtNs<=x.after.observedAtNs && x.before.observedAtNs>0 && x.before.observedAtUnixMs>0); const auto a=J::parse(commonWorldRuntimeDiagnostics(x.before,{},"test")); const auto b=J::parse(commonWorldRuntimeDiagnostics(x.after,{},"test")); CHECK(a["observed_at_monotonic_ns"]==x.before.observedAtNs && b["observed_at_monotonic_ns"]==x.after.observedAtNs); });
 std::cout<<"PASS "<<cases<<" A2 control cases / "<<checks<<" assertions; deterministic software-only; no production endpoint"<<std::endl; return 0;
} catch(const std::exception& e) { std::cerr<<"FAIL "<<e.what()<<" cases="<<cases<<" checks="<<checks<<std::endl; return 1; }
